//select between normalizing brightness across whole image, or just one column.
const bool globalBiggest = false;
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;


    // Picture in picture
    const float pipStartx = .7;
    const float pipEndy = .3;

    if(uv.x > pipStartx && uv.y < pipEndy)
    {
        fragColor = texture(iChannel2, (uv - vec2(pipStartx, 0)) * (vec2(1) / (vec2(1. - pipStartx, pipEndy))));
        if(distance(fragColor.xyz, vec3(13./255., 163. / 255., 38. / 255.)) >= 0.25)
            return;
    }

    //display results from A and B

    ivec2 size = textureSize(iChannel0, 0);

    ivec2 pixCoord = ivec2(uv * vec2(size));

    vec3 s = texelFetch(iChannel0, pixCoord, 0).rgb;

    if(globalBiggest)
    {
        vec3 gBiggest = vec3(0);
        for(int i = 0; i < size.x; i++)
        {
            vec3 s = texelFetch(iChannel1, ivec2(i,0), 0).rgb;
            gBiggest = max(s,gBiggest);
        }
        fragColor = vec4(s/gBiggest,1.0);
    } else {
        fragColor = vec4(s/texelFetch(iChannel1, ivec2(pixCoord.x,0), 0).rgb,1.0);
    }


}

float srgb_to_linear(float u)
{
    const float U = 0.04045;
    const float A = 12.92;
    const float C = 0.055;
    const float gamma = 2.4;
    if(u <= U)
        return u / A;
    else
        return pow((u+C)/(1.+C), gamma);
}

float linear_to_srgb(float v)
{
    const float V = 0.0031308;
    const float A = 12.92;
    const float C = 0.055;
    const float gamma = 2.4;
    if(v <= V)
        return A*v;
    else
        return (1. + C)*pow(v,1./gamma) - C;
}

vec3 srgb_to_linear(vec3 srgb)
{
    vec3 linRGB;
    linRGB.r = srgb_to_linear(srgb.r);
    linRGB.g = srgb_to_linear(srgb.g);
    linRGB.b = srgb_to_linear(srgb.b);
    return linRGB;
}

vec3 linear_to_srgb(vec3 linRGB)
{
    vec3 srgb;
    srgb.r = linear_to_srgb(linRGB.r);
    srgb.g = linear_to_srgb(linRGB.g);
    srgb.b = linear_to_srgb(linRGB.b);
    return srgb;
}

float luma(vec3 linrgb)
{
    return linrgb.r * 0.2126 + linrgb.g * 0.7152 + linrgb.b * 0.0722;
}

const bool parade = false;
vec3 histogramColor(vec2 iuv)
{
    ivec2 imageRes = textureSize(iChannel0, 0);
    vec2 uv = iuv;

    if(parade)
    {
        uv.x *= 3.;
        uv.x = mod(uv.x, 1.);
    }

    float rangePerPixel = 1./iResolution.y;
    rangePerPixel = max(rangePerPixel, 1./256.);
    float upperlimit = uv.y + rangePerPixel;
    float lowerlimit = uv.y;

    vec3 sum = vec3(0.);
    for(int y = 0; y < imageRes.y; y++)
    {
        vec3 col = texelFetch(iChannel0, ivec2(int(uv.x*float(imageRes.x)), y), 0).rgb;
        //filter out chroma key color
        if(distance(col, vec3(13./255., 163. / 255., 38. / 255.)) < 0.25)
            col = vec3(0,0,0);

        //col = srgb_to_linear(col);


        if(col.r >= lowerlimit && col.r < upperlimit)
            sum.r += 1.;
        if(col.g >= lowerlimit && col.g < upperlimit)
            sum.g += 1.;
        if(col.b >= lowerlimit && col.b < upperlimit)
            sum.b += 1.;
    }

    //Old attempts at mapping the histogram values to a visual range
    //sum /= vec3(imageRes.y);
    //sum = log(sum * vec3(0.9) + vec3(0.1))/log(10.0) + vec3(1);
    //sum = pow(sum,vec3(1./10.));

    if(parade)
    {
        if(iuv.x < 1./3.)
            sum = vec3(sum.r,0,0);
        else if(iuv.x < 2./3.)
            sum = vec3(0,sum.g,0);
        else
            sum = vec3(0,0,sum.b);
    }

    return sum;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    vec3 col = histogramColor(uv);

    // Output to screen
    fragColor = vec4(col,1.0);
}

// Buffer B is used to reduce duplicate work normalizing the histogram to the 0-1 range

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //use the bottom row of pixels to record biggest value
    if(fragCoord.y > 1.)
        return;
    vec2 uv = fragCoord/iResolution.xy;

    ivec2 size = textureSize(iChannel0, 0);

    vec3 biggest = vec3(0.);
    for(int i = 0; i < size.y; i++)
    {
        ivec2 pc = ivec2(uv.x * float(size.x), i);
        vec3 s = texelFetch(iChannel0, pc, 0).rgb;
        biggest = max(s,biggest);
    }

    // Output to screen
    fragColor = vec4(biggest,1.0);
}
